#include "KrollGeneratedBindings.h"

#define TAG "KrollBindings"

namespace titanium {

std::map<std::string, bindings::BindEntry*> KrollBindings::externalBindings;
std::map<std::string, jobject> KrollBindings::externalCommonJsModules;
std::map<std::string, jmethodID> KrollBindings::commonJsSourceRetrievalMethods;
std::vector<LookupFunction> KrollBindings::externalLookups;
std::map<std::string, bindings::BindEntry*> KrollBindings::externalLookupBindings;

// The bindings that the runtime implements itself. The V8 runtime builds this table with gperf.
// Five entries do not need a perfect hash.
static bindings::BindEntry nativeBindings[] = {
	{ "natives", KrollBindings::initNatives, NULL },
	{ "evals", ScriptsModule::Initialize, ScriptsModule::Dispose },
	{ "assets", AssetsModule::Initialize, NULL },
	{ "API", APIModule::Initialize, APIModule::Dispose },
	{ "Titanium", KrollBindings::initTitanium, KrollBindings::disposeTitanium }
};

static bindings::BindEntry* lookupNativeBinding(const std::string& name)
{
	for (bindings::BindEntry& entry : nativeBindings) {
		if (name == entry.name) {
			return &entry;
		}
	}
	return NULL;
}

void KrollBindings::initFunctions(jsi::Runtime& rt, const jsi::Object& exports)
{
	// kroll.binding(name)
	JSUtil::setMethod(rt, exports, "binding", 1,
		[](jsi::Runtime& rt, const jsi::Value&, const jsi::Value* args, size_t count) -> jsi::Value {
			if (count == 0 || !args[0].isString()) {
				JSException::Error(rt, "Invalid arguments to binding, expected String");
			}
			return KrollBindings::getBinding(rt, args[0].getString(rt).utf8(rt));
		});

	// kroll.externalBinding(name): looks up bindings of native modules only.
	JSUtil::setMethod(rt, exports, "externalBinding", 1,
		[](jsi::Runtime& rt, const jsi::Value&, const jsi::Value* args, size_t count) -> jsi::Value {
			if (count == 0 || !args[0].isString()) {
				JSException::Error(rt, "Invalid arguments to externalBinding, expected String");
			}
			std::string name = args[0].getString(rt).utf8(rt);
			jsi::Object& cache = TiRuntime::state->bindingCache;
			jsi::Value cached = cache.getProperty(rt, jsi::PropNameID::forUtf8(rt, name));
			if (cached.isObject()) {
				return cached;
			}
			return KrollBindings::instantiateBinding(rt,
				KrollBindings::getExternalBinding(name.c_str(), (unsigned int) name.length()), name);
		});

	// kroll.isExternalCommonJsModule(name)
	JSUtil::setMethod(rt, exports, "isExternalCommonJsModule", 1,
		[](jsi::Runtime& rt, const jsi::Value&, const jsi::Value* args, size_t count) -> jsi::Value {
			if (count == 0 || !args[0].isString()) {
				JSException::Error(rt, "Invalid arguments to isExternalCommonJsModule, expected String");
			}
			std::string name = args[0].getString(rt).utf8(rt);
			return jsi::Value(externalCommonJsModules.count(name) > 0);
		});

	// kroll.getExternalCommonJsModule(name): asks the KrollSourceCodeProvider of a native module
	// for the source of a CommonJS module that the native module contains.
	JSUtil::setMethod(rt, exports, "getExternalCommonJsModule", 1,
		[](jsi::Runtime& rt, const jsi::Value&, const jsi::Value* args, size_t count) -> jsi::Value {
			if (count == 0 || !args[0].isString()) {
				JSException::Error(rt, "Invalid arguments to getExternalCommonJsBinding, expected String");
			}
			std::string nameKey = args[0].getString(rt).utf8(rt);
			std::string moduleRoot = nameKey;
			std::string subPath = nameKey;

			size_t slashPos = nameKey.find('/');
			if (slashPos != std::string::npos) {
				moduleRoot = nameKey.substr(0, slashPos);
				subPath = nameKey.substr(slashPos + 1);
			}

			if (externalCommonJsModules.count(moduleRoot) == 0) {
				return jsi::Value::undefined();
			}

			JNIEnv* env = JNIScope::getEnv();
			if (!env) {
				JSException::GetJNIEnvironmentError(rt);
			}
			jobject sourceProvider = externalCommonJsModules[moduleRoot];
			jmethodID sourceRetrievalMethod = commonJsSourceRetrievalMethods[moduleRoot];

			// The older version of KrollSourceCodeProvider.getSourceCode() took no arguments,
			// because one native module could contain one CommonJS module only. Some modules still
			// have that version. Try the newer getSourceCode(String) first.
			jstring javaSubPath = env->NewStringUTF(subPath.c_str());
			jstring sourceJavaString = (jstring) env->CallObjectMethod(sourceProvider, sourceRetrievalMethod, javaSubPath);
			env->DeleteLocalRef(javaSubPath);

			if (env->ExceptionCheck() && slashPos == std::string::npos) {
				// Try the old, no-arg way of getting source, but only if the root module is requested.
				env->ExceptionClear();
				jclass providerClass = env->GetObjectClass(sourceProvider);
				sourceRetrievalMethod = env->GetMethodID(providerClass, "getSourceCode", "()Ljava/lang/String;");
				env->DeleteLocalRef(providerClass);
				if (sourceRetrievalMethod) {
					sourceJavaString = (jstring) env->CallObjectMethod(sourceProvider, sourceRetrievalMethod);
				}
			}
			if (env->ExceptionCheck()) {
				env->ExceptionClear();
				return jsi::Value::null();
			}

			jsi::Value sourceCode = TypeConverter::javaStringToJsString(rt, env, sourceJavaString);
			if (sourceJavaString) {
				env->DeleteLocalRef(sourceJavaString);
			}
			return sourceCode;
		});
}

void KrollBindings::initNatives(jsi::Runtime& rt, const jsi::Object& exports)
{
	for (int i = 0; natives[i].name; ++i) {
		if (natives[i].source == kroll_native) {
			continue;
		}
		exports.setProperty(rt, natives[i].name,
			jsi::String::createFromUtf8(rt, reinterpret_cast<const uint8_t*>(natives[i].source), natives[i].source_length));
	}
}

void KrollBindings::initTitanium(jsi::Runtime& rt, const jsi::Object& exports)
{
	JNIEnv* env = JNIScope::getEnv();
	if (!env) {
		LOGE(TAG, "Couldn't initialize JNIEnv");
		return;
	}

	Proxy::bindProxy(rt, exports);
	KrollProxy::bindProxy(rt, exports);
	KrollModule::bindProxy(rt, exports);
	TitaniumModule::bindProxy(rt, exports);
}

void KrollBindings::disposeTitanium(jsi::Runtime& rt)
{
	KrollProxy::dispose(rt);
	KrollModule::dispose(rt);
	TitaniumModule::dispose(rt);
}

std::string KrollBindings::getMainSource()
{
	return std::string(kroll_native, sizeof(kroll_native) - 1);
}

jsi::Value KrollBindings::instantiateBinding(jsi::Runtime& rt, bindings::BindEntry* binding, const std::string& key)
{
	if (!binding) {
		return jsi::Value::undefined();
	}
	jsi::Object exports(rt);
	binding->bind(rt, exports);
	TiRuntime::state->bindingCache.setProperty(rt, jsi::PropNameID::forUtf8(rt, key), exports);
	return exports;
}

bindings::BindEntry* KrollBindings::getExternalBinding(const char *name, unsigned int length)
{
	auto it = externalBindings.find(std::string(name));
	return it == externalBindings.end() ? NULL : it->second;
}

void KrollBindings::addExternalBinding(const char *name, struct bindings::BindEntry *binding)
{
	LOGD(TAG, "Registered external (native module) binding for name %s", name);
	externalBindings[std::string(name)] = binding;
}

void KrollBindings::addExternalLookup(LookupFunction lookup)
{
	externalLookups.push_back(lookup);
}

jsi::Value KrollBindings::getBinding(jsi::Runtime& rt, const std::string& binding)
{
	// If in the cache, return it. Otherwise fall back to generating it.
	jsi::Value cached = TiRuntime::state->bindingCache.getProperty(rt, jsi::PropNameID::forUtf8(rt, binding));
	if (cached.isObject()) {
		return cached;
	}

	unsigned int length = (unsigned int) binding.length();

	// Try natives
	jsi::Value exports = instantiateBinding(rt, lookupNativeBinding(binding), binding);
	if (exports.isObject()) {
		return exports;
	}

	// Try generated proxies (Titanium APIs)
	exports = instantiateBinding(rt, bindings::generated::lookupGeneratedInit(binding.c_str(), length), binding);
	if (exports.isObject()) {
		return exports;
	}

	// Try native modules by lookup function.
	for (size_t i = 0; i < externalLookups.size(); i++) {
		struct bindings::BindEntry* external = (*externalLookups[i])(binding.c_str(), length);
		if (external) {
			exports = instantiateBinding(rt, external, binding);
			externalLookupBindings[binding] = external;
			return exports;
		}
	}

	// Try native modules by binding string
	exports = instantiateBinding(rt, getExternalBinding(binding.c_str(), length), binding);
	if (!exports.isObject()) {
		LOGD(TAG, "No binding found for %s, returning undefined", binding.c_str());
	}
	return exports;
}

// Disposes what the generated and native bindings cached, and clears the module lookup cache.
void KrollBindings::dispose(jsi::Runtime& rt)
{
	JNIEnv *env = JNIScope::getEnv();
	if (env) {
		for (auto& entry : externalCommonJsModules) {
			env->DeleteGlobalRef(entry.second);
		}
	}
	externalCommonJsModules.clear();
	commonJsSourceRetrievalMethods.clear();

	// Dispose all external bindings
	for (auto& entry : externalBindings) {
		bindings::BindEntry *external = entry.second;
		if (external && external->dispose) {
			external->dispose(rt);
		}
	}

	if (!TiRuntime::state) {
		externalLookupBindings.clear();
		return;
	}

	jsi::Array names = TiRuntime::state->bindingCache.getPropertyNames(rt);
	size_t length = names.size(rt);
	for (size_t i = 0; i < length; i++) {
		std::string binding = names.getValueAtIndex(rt, i).toString(rt).utf8(rt);
		unsigned int bindingLength = (unsigned int) binding.length();

		struct bindings::BindEntry *generated = bindings::generated::lookupGeneratedInit(binding.c_str(), bindingLength);
		if (generated && generated->dispose) {
			generated->dispose(rt);
			continue;
		}

		struct bindings::BindEntry *native = lookupNativeBinding(binding);
		if (native && native->dispose) {
			native->dispose(rt);
			continue;
		}

		auto lookup = externalLookupBindings.find(binding);
		if (lookup != externalLookupBindings.end() && lookup->second && lookup->second->dispose) {
			lookup->second->dispose(rt);
		}
	}

	externalLookupBindings.clear();
	TiRuntime::state->bindingCache = jsi::Object(rt);
}

// Stores a Java KrollSourceCodeProvider instance and the id of its getSourceCode method
// for an external CommonJS module that is stored in a Java external module.
void KrollBindings::addExternalCommonJsModule(const char *name, jobject sourceProvider, jmethodID sourceRetrievalMethod)
{
	std::string stringName(name);
	externalCommonJsModules[stringName] = sourceProvider;
	commonJsSourceRetrievalMethods[stringName] = sourceRetrievalMethod;
}

} // namespace titanium
